<?php
declare(strict_types=1);
$dir=sys_get_temp_dir().'/ectro-readiness-admin-'.bin2hex(random_bytes(6));mkdir($dir,0700);putenv('APP_DATA_DIR='.$dir);putenv('APP_ENV=development');putenv('APP_KEY='.base64_encode(random_bytes(32)));
register_shutdown_function(function()use($dir){foreach(glob($dir.'/*') as $f)unlink($f);rmdir($dir);});
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/templates.php';require __DIR__.'/../app/mysql.php';require __DIR__.'/../app/lab-api.php';
$checks=0;function check(bool $v,string $why):void{global $checks;$checks++;if(!$v)throw new RuntimeException($why);}function rejects(int $status,callable $f):void{try{$f();throw new RuntimeException('Expected rejection');}catch(ApiError $e){check($e->status===$status,$e->getMessage());}}
function person(string $name,string $role='user'):array{$uid=id();query('INSERT INTO users(id,name,email,password,role,created_at) VALUES(?,?,?,?,?,?)',[$uid,$name,$uid.'@example.test','unused',$role,now()]);return one('SELECT * FROM users WHERE id=?',[$uid]);}
$a=person('Admin','admin');$u=person('Alice');$v=person('Bob');$none=person('No check');$outsider=person('Outside');$g=id();$expired=id();foreach([$g,$expired] as $gid)query('INSERT INTO groups(id,name,created_at) VALUES(?,?,?)',[$gid,$gid,now()]);foreach([$u,$v,$none] as $p)query('INSERT INTO group_members VALUES(?,?)',[$g,$p['id']]);query('INSERT INTO group_members VALUES(?,?)',[$expired,$u['id']]);saveGroupPeriods($expired,groupPeriodsInput(['access_end'=>'2020-01-01']));
$catalog=json_decode(file_get_contents(__DIR__.'/../app/readiness-catalog.json'),true);$c=['schemaVersion'=>1,'organization'=>'Company','scope'=>'organization','area'=>'','baseline'=>'connected','answers'=>array_fill_keys(array_column($catalog['criteria'],'id'),'yes'),'screen'=>'result','step'=>9,'completedAt'=>'2026-11-09T09:00:00.000Z'];
$p=createProject($u,'Personal','web');$o=labSave($u,['project'=>$p,'kind'=>'readiness','name'=>'Alice result','content'=>$c]);$sp=createProject($u,'Group','web',$g);$shared=labSave($u,['project'=>$sp,'kind'=>'readiness','name'=>'Team','content'=>$c]);$edited=$c;$edited['answers']['workflows']='partial';$shared=labSave($v,['project'=>$sp,'id'=>$shared['id'],'version'=>$shared['version'],'kind'=>'readiness','name'=>'Team','content'=>$edited]);
foreach([$u,$v,['role'=>'teacher']] as $x){rejects(403,fn()=>readinessAdminDirectory($x));rejects(403,fn()=>readinessAdminOverview($x,[]));rejects(403,fn()=>readinessAdminDetail($x,['id'=>$o['id']]));}
$dirData=readinessAdminDirectory($a);check(count($dirData['groups'])===2,'Expired groups remain available');check(!isset($dirData['people'][0]['password']),'Directory has no secrets');
$overview=readinessAdminOverview($a,['group'=>$g]);check($overview['total']===2,'Group includes private member and direct group project');check(count($overview['participants'])===3,'Includes participants without checks, excludes outsiders');check($overview['summary']['complete']===2&&$overview['summary']['shared']===1,'Shared check counted once');check(array_sum($overview['distribution'])===2,'Distribution uses one current version per check');
$bob=readinessAdminOverview($a,['person'=>$v['id']]);check($bob['total']===1&&$bob['checks'][0]['actor_id']===$v['id'],'Person filter finds actual shared editor');check($bob['participants'][0]['complete']===0,'Shared result does not masquerade as personal result');
$alice=readinessAdminOverview($a,['person'=>$u['id']]);check($alice['total']===2,'Previous contributing editor remains findable');
$detail=readinessAdminDetail($a,['id'=>$shared['id']]);check($detail['check']['actor_id']===$v['id']&&$detail['check']['version']===2,'Current editor cannot be forged by client');check($detail['previous']['answers']['workflows']==='yes','Prior answers preserved');check(count($detail['revisions'])===2,'Saved revisions retained');$old=readinessAdminDetail($a,['id'=>$shared['id'],'version'=>'1']);check($old['check']['actor_id']===$u['id']&&$old['check']['report']['score']===7.0,'History uses correct actor and own score');
rejects(409,fn()=>labSave($v,['project'=>$sp,'id'=>$shared['id'],'version'=>1,'kind'=>'readiness','name'=>'Stale','content'=>$c]));check(count(readinessAdminDetail($a,['id'=>$shared['id']])['revisions'])===2,'Rejected saves do not create history');
$draft=[...$c,'screen'=>'questions','completedAt'=>'','answers'=>['workflows'=>'partial']];labSave($v,['project'=>createProject($v,'Draft','web'),'kind'=>'readiness','name'=>'Draft','content'=>$draft]);$drafts=readinessAdminOverview($a,['status'=>'draft']);check($drafts['total']===1&&array_sum($drafts['distribution'])===0,'Drafts excluded from score distribution');
$legacy=id();query('INSERT INTO lab_objects(id,project_id,kind,name,content,updated_at) VALUES(?,?,?,?,?,?)',[$legacy,$p,'readiness','Legacy',labJson($c),now()]);$legacyDetail=readinessAdminDetail($a,['id'=>$legacy]);check($legacyDetail['check']['actor_id']===null,'Legacy attribution remains unknown');labSave($u,['project'=>$p,'id'=>$legacy,'version'=>1,'kind'=>'readiness','name'=>'Legacy','content'=>$edited]);check(readinessAdminDetail($a,['id'=>$legacy,'version'=>1])['check']['actor_id']===null,'Legacy predecessor preserved without inventing authorship');
$expiredView=readinessAdminOverview($a,['group'=>$expired]);check($expiredView['total']===2,'Expired group report retains private checks without granting learner access');
rejects(422,fn()=>readinessAdminOverview($a,['status'=>'bad']));rejects(422,fn()=>readinessAdminOverview($a,['page'=>'-1']));rejects(404,fn()=>readinessAdminOverview($a,['group'=>str_repeat('a',32)]));rejects(404,fn()=>readinessAdminDetail($a,['id'=>$o['id'],'version'=>99]));
for($i=0;$i<52;$i++)query('INSERT INTO lab_objects(id,project_id,kind,name,content,updated_at) VALUES(?,?,?,?,?,?)',[id(),$p,'readiness','Pagination '.str_pad((string)$i,2,'0',STR_PAD_LEFT),labJson($c),now()]);$first=readinessAdminOverview($a,[]);$second=readinessAdminOverview($a,['page'=>'2']);check(count($first['checks'])===50&&count($second['checks'])===6,'Bounded stable pages, full aggregate');check(!array_intersect(array_column($first['checks'],'id'),array_column($second['checks'],'id')),'No duplicate records between pages');check($first['summary']['complete']===55,'Summary counts all pages');
query('DELETE FROM users WHERE id=?',[$v['id']]);check(readinessAdminDetail($a,['id'=>$shared['id']])['check']['actor_id']===null,'Deleted actor is anonymized while shared result remains');
query('DELETE FROM lab_objects WHERE id=?',[$shared['id']]);check((int)query('SELECT COUNT(*) FROM readiness_revisions WHERE object_id=?',[$shared['id']])->fetchColumn()===0,'Deletion cascades to answers/history');
$fixtures=json_decode(stream_get_contents(STDIN),true);if($fixtures){$output=[];foreach($fixtures as $content)$output[]=readinessScore($content);echo json_encode($output);}
fwrite(STDERR,"$checks readiness admin access, filters, history, attribution, expiry, drafts, pagination and deletion checks passed.\n");
